import React, { forwardRef } from 'react';
import styled from 'styled-components';

import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';

//#region Typings
/** Accepted properties for the TitleBar Navigation */
export interface TitleBarNavigationProps extends StylingProps, DataTestId {
  /** Elements to be displayed in the TitleBar Navigation slot. */
  children: React.ReactNode;
}
//#endregion

//#region Styled Components
const StyledNavigationWrapper = /* @__PURE__ */ styled('div')({
  flexGrow: 1,
  alignSelf: 'center',
  minWidth: 0,
});
//#endregion

/** TitleBar Navigation component */
export const Navigation = /* @__PURE__ */ forwardRef<
  HTMLDivElement,
  TitleBarNavigationProps
>((props, forwardedRef) => {
  const {
    children,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
  }: TitleBarNavigationProps = props;

  return (
    <StyledNavigationWrapper
      ref={forwardedRef}
      className={consumerClassName}
      style={consumerStyle}
      data-testid={dataTestId}
    >
      {children}
    </StyledNavigationWrapper>
  );
});
